import os,sys,runpy
from pathlib import Path
private=Path('/Users/sasha/medusa/research/leemans')
def audit(event,args):
 if event == 'open' and isinstance(args[0],(str,bytes,os.PathLike)):
  p=Path(os.fsdecode(args[0])).resolve()
  if p == private or private in p.parents: raise RuntimeError('PRIVATE_RESEARCH_READ_DENIED')
 if event in ('subprocess.Popen','os.system','os.posix_spawn','socket.connect'): raise RuntimeError('EXTERNAL_EXECUTION_DENIED')
sys.addaudithook(audit)
script=sys.argv[1];sys.argv=sys.argv[1:]
runpy.run_path(script,run_name='__main__')
